//! ABI-stable cdylib export for the `readarr` plugin.
//!
//! Tool-surface plugin: the entire export is generated by the toolkit's
//! [`export_tool_plugin!`] — the metadata fns, the `readarr.`-filtered manifest,
//! the dispatch `invoke`, host-service wiring (`set_host`/`set_secret_op`, so
//! the through-core `endpoint_db` access works), and empty `backends`/`schemas`.
#![allow(clippy::disallowed_types)]

plugin_toolkit::export_tool_plugin! {
    name: "readarr",
    target_compat: "readarr=v1",
    tool_prefixes: ["readarr."],
}
